// Dinkumware-era max source shape used by retail: arguments are copied into
// homes and the selected home is returned by reference.
template <class T>
inline const T& _cpp_max(T left, T right)
{
    return left < right ? right : left;
}

// The [-3, 3] rating selector the one-army constructor CALLS at
// 0x4e6750 (33 B, `ret 4`). Three CONST REFERENCES, not values: the
// body dereferences ecx and edx and returns one of the three incoming
// pointers, and the caller materialises -3 and 3 into homes of their
// own to have addresses to pass. The branch graph fixes both the
// parameter order and the expression - `mov eax,[ecx] / mov esi,[edx] /
// cmp esi,eax / jge` returns argument ONE when argument TWO is below
// it, then `cmp [arg3],esi / jl` keeps argument three - i.e.
// (_Lo, _V, _Hi) and `_V < _Lo ? _Lo : _Hi < _V ? _Hi : _V`, with the
// low bound tested first. ai_tactical.cpp's own three-operand clamp is
// the same selector under a different parameter order (_V, _Hi, _Lo)
// and by value; that TU only ever sees it INLINED, so its order is
// inferred from home-materialisation while this one is read straight
// off an out-of-line body.
// DECLARED, NOT DEFINED - the same treatment textWidget::SetText and
// combatManager::mark_moat get. Retail's copy is a COMDAT the linker
// parked at 0x4e6750, i.e. this TU never saw a body to expand; giving
// our CL one makes it inline the selector at both icon rows where
// retail calls it.
const int& _cpp_clamp(const int& _Lo, const int& _V, const int& _Hi);

// Two representation bridges in game.cpp's/ai_combat.cpp's shape - a
// four-byte copy VC6 reduces to a move - so that neither a
// reinterpret_cast nor an enum cast appears here:
//
//  * army.h models the traits row EVERY stack carries embedded at +0x74
//    as a handful of sliced ints, `monInfoTownType` first, because
//    modelling the record itself is a layout change for the whole army
//    run (army.h says so at the slice). Retail's constructor takes the
//    row's address once and hands it to three widget builders, so this
//    TU needs the record view. Draining this belongs to whoever gives
//    army a real `TCreatureTypeTraits sMonInfo`.
//  * armyGroup's describers take TCreatureType where army::creatureType
//    and this window's own ArmyType are both spelled int for the same
//    header-closure reason.
inline const TCreatureTypeTraits* stack_traits_of(const int* first_field)
{
    union {
        const int* field;
        const TCreatureTypeTraits* traits;
    } storage;
    storage.field = first_field;
    return storage.traits;
}

inline TCreatureType creature_type_from_int(int value)
{
    union {
        int value;
        TCreatureType creature;
    } storage;
    storage.value = value;
    return storage.creature;
}

